# Find all connected components
def find_components_of_color(color):
    visited = [[False]*17 for _ in range(28)]
    components = []

    for r in range(28):
        for c in range(17):
            if grid[r][c] == color and not visited[r][c]:
                # BFS to find all connected
                comp = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 28 and 0 <= nc < 17:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                components.append(comp)
    return components

print("Connected components for each color:")
for color in [2, 3, 5, 7, 9]:
    comps = find_components_of_color(color)
    print(f"  Color {color}: {len(comps)} components")
    for i, comp in enumerate(comps[:3]):
        comp_rows = sorted(set(r for r, c in comp))
        comp_cols = sorted(set(c for r, c in comp))
